REVIEW REQUEST: I (Claude) wrote this waveform + gate-flow JavaScript SOLO after the team voted on the design. Ross caught me ("ps are u working solo?") — I should have had team write the implementation too. Please review for bugs, common mistakes, and improvements. Ross also says it's "not working" after page refresh.

THE CODE I WROTE (161 lines, vanilla JS, runs in a dashboard at http://127.0.0.1:8847/ that polls /api/traders_live every 2s):

```javascript
const WAVE_TRACKS = ["regime","trend","volatility","cross_asset","convergence"];
const WAVE_COLORS = {regime:"#88f0d8",trend:"#f6c45a",volatility:"#44ad6a",
                     cross_asset:"#ff5050",convergence:"#ffffff"};
const WAVE_BUFFER_SIZE = 240;
const waveBuffers = {regime:[], trend:[], volatility:[], cross_asset:[], convergence:[]};
let waveLastFrame = 0, waveFps = 0, waveFrames = 0, waveFpsLast = 0;
let waveAnimRunning = false;

function pushWaveSample(convergenceData) {
  if (!convergenceData || !convergenceData.length) return;
  const n = convergenceData.length;
  const dimCounts = {regime:0, trend:0, volatility:0, cross_asset:0};
  let firingCount = 0;
  for (const w of convergenceData) {
    if (w.ok) firingCount++;
    for (const d of (w.dims_passed || [])) {
      if (dimCounts.hasOwnProperty(d)) dimCounts[d]++;
    }
  }
  for (const dim of ["regime","trend","volatility","cross_asset"]) {
    waveBuffers[dim].push(dimCounts[dim] / n);
    if (waveBuffers[dim].length > WAVE_BUFFER_SIZE) waveBuffers[dim].shift();
  }
  waveBuffers.convergence.push(firingCount / n);
  if (waveBuffers.convergence.length > WAVE_BUFFER_SIZE) waveBuffers.convergence.shift();
}

function drawWaves() {
  const c = document.getElementById("wave-canvas");
  if (!c) return;
  const ctx = c.getContext("2d");
  const W = c.clientWidth || 900, H = c.clientHeight || 280;
  if (c.width !== W) c.width = W;
  if (c.height !== H) c.height = H;
  ctx.clearRect(0,0,W,H);
  // background grid
  ctx.strokeStyle = "rgba(80,220,180,0.06)";
  ctx.lineWidth = 1;
  for (let y = 0; y <= 4; y++) {
    ctx.beginPath();
    ctx.moveTo(0, y*H/4); ctx.lineTo(W, y*H/4); ctx.stroke();
  }
  WAVE_TRACKS.forEach((track, i) => {
    const buf = waveBuffers[track];
    if (!buf.length) return;
    const color = WAVE_COLORS[track];
    const isHeadline = track === "convergence";
    const trackH = isHeadline ? H * 0.45 : H * 0.45;
    const trackTop = isHeadline ? H * 0.55 : 0;
    // gradient fill
    ctx.beginPath();
    ctx.moveTo(0, trackTop + trackH);
    for (let x = 0; x < buf.length; x++) {
      const px = (x / WAVE_BUFFER_SIZE) * W;
      const py = trackTop + trackH - (buf[x] * trackH);
      if (x === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.lineTo((buf.length / WAVE_BUFFER_SIZE) * W, trackTop + trackH);
    ctx.closePath();
    const grad = ctx.createLinearGradient(0, trackTop, 0, trackTop + trackH);
    grad.addColorStop(0, color + (isHeadline ? "55" : "33"));
    grad.addColorStop(1, color + "00");
    ctx.fillStyle = grad;
    ctx.fill();
    // line
    ctx.beginPath();
    for (let x = 0; x < buf.length; x++) {
      const px = (x / WAVE_BUFFER_SIZE) * W;
      const py = trackTop + trackH - (buf[x] * trackH);
      if (x === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.strokeStyle = color;
    ctx.lineWidth = isHeadline ? 2.0 : 1.2;
    ctx.stroke();
  });
}

function startWaveAnim() {
  if (waveAnimRunning) return;
  waveAnimRunning = true;
  function loop() { drawWaves(); requestAnimationFrame(loop); }
  requestAnimationFrame(loop);
}
```

